lab.solution:
def classification_loss(logits, target):
    import math
    peak = max(logits)
    log_z = peak+math.log(sum(math.exp(v-peak) for v in logits))
    if isinstance(target, int):
        return log_z-logits[target]
    return sum(weight*(log_z-value) for weight,value in zip(target,logits))

